 final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();volatile boolean closed=false;final MainActivity a;final StudyStore db;final SharedPreferences prefs;LinearLayout content;String section="Cursos",query="";long course=0,subject=0;int limit=80,libraryPage=0;boolean loading=false;volatile int generation;List<StudyStore.Row> subjects=new ArrayList<>(),courses=new ArrayList<>();final Map<String,List<StudyStore.Row>> data=new HashMap<>();long[] totals=new long[9];StudyToday.Snapshot today=new StudyToday.Snapshot();TextView timerLabel;final Handler clock=new Handler(Looper.getMainLooper());
 StudyHub(MainActivity activity){a=activity;db=new StudyStore(a);prefs=a.getSharedPreferences("studies",0);course=prefs.getLong("course",0);subject=prefs.getLong("subject",0);section=prefs.getString("section","Cursos");if(!prefs.getBoolean("courses_ui_v1",false)){course=0;subject=0;section="Cursos";prefs.edit().putBoolean("courses_ui_v1",true).putLong("course",0).putLong("subject",0).putString("section","Cursos").apply();}}
