 void reload(){if(a.dead)return;final int request=++generation;final long selectedCourse=course,filter=subject;final String q=query;final int page=limit,requestedLibraryPage=libraryPage;final String active=section;loading=true;job(()->{if(request!=generation||closed)return;List<StudyStore.Row> courseRows=db.courses();long validCourse=selectedCourse;boolean courseFound=validCourse==0;for(StudyStore.Row c:courseRows)if(c.id()==validCourse)courseFound=true;if(!courseFound)validCourse=0;final long loadedCourse=validCourse;List<StudyStore.Row> groups=db.rows("subjects",validCourse>0?"course=?":null,validCourse>0?new String[]{""+validCourse}:null,"title COLLATE NOCASE",500);Map<Long,long[]> moduleStats=new HashMap<>();try(Cursor stats=db.getReadableDatabase().rawQuery("SELECT subject,COUNT(*),CAST(AVG(progress) AS INTEGER) FROM materials GROUP BY subject",null)){while(stats.moveToNext())moduleStats.put(stats.getLong(0),new long[]{stats.getLong(1),stats.getLong(2)});}for(StudyStore.Row group:groups){long[] item=moduleStats.get(group.id());group.put("material_count",item==null?"0":""+item[0]);group.put("progress",item==null?"0":""+item[1]);}boolean subjectFound=filter==0;for(StudyStore.Row g:groups)if(g.id()==filter)subjectFound=true;final long loadedSubject=subjectFound?filter:0;Map<String,List<StudyStore.Row>> result=new HashMap<>();String scope=StudyStore.scope(loadedCourse,loadedSubject);String[] tables={"materials","notes","cards","questions","tasks","sessions","quiz_runs"};long[] stats=new long[9];int actualLibraryPage=0;for(int i=0;i<tables.length;i++){String t=tables[i],clause=scope;String[] args=null;stats[i]=active.equals("Cursos")||active.equals("Módulos")?0:db.count(t,scope,null);boolean needed=active.equals("Progresso")&&(t.equals("sessions")||t.equals("quiz_runs"))||active.equals("Biblioteca")&&t.equals("materials")||active.equals("Cadernos")&&t.equals("notes")||active.equals("Cartões")&&t.equals("cards")||active.equals("Perguntas")&&t.equals("questions")||active.equals("Agenda")&&t.equals("tasks");if(!needed){result.put(t,Collections.emptyList());continue;}if(!q.isEmpty()){String columns=t.equals("materials")?"title||' '||author||' '||name":t.equals("notes")?"title||' '||body||' '||tags":t.equals("cards")?"front||' '||back||' '||tags":t.equals("questions")?"prompt||' '||answer||' '||tags":t.equals("tasks")?"title":t.equals("sessions")?"goal":"details";clause+=" AND ("+columns+") LIKE ? ESCAPE '\\'";args=new String[]{StudySchedule.like(q)};}String order=t.equals("cards")?"suspended,due,id":t.equals("tasks")?"done,CASE WHEN due=0 THEN 1 ELSE 0 END,due,priority DESC,id":"id DESC";if(t.equals("materials")&&active.equals("Biblioteca")){stats[0]=db.count(t,clause,args);actualLibraryPage=Math.min(requestedLibraryPage,Math.max(0,(int)((stats[0]-1)/12)));result.put(t,db.page(t,clause,args,order,12,actualLibraryPage*12));}else result.put(t,db.rows(t,clause,args,order,t.equals("sessions")||t.equals("quiz_runs")?1000:page));}stats[7]=active.equals("Cursos")||active.equals("Módulos")?0:db.count("cards",scope+" AND suspended=0 AND due<="+System.currentTimeMillis(),null);stats[8]=active.equals("Cursos")||active.equals("Módulos")?0:db.count("tasks",scope+" AND done=0",null);final StudyToday.Snapshot loadedToday=StudyToday.load(db,loadedCourse,loadedSubject,System.currentTimeMillis());final int loadedLibraryPage=actualLibraryPage;a.ui(()->{if(request!=generation)return;libraryPage=loadedLibraryPage;loading=false;courses=courseRows;course=loadedCourse;subject=loadedSubject;subjects=groups;data.clear();data.putAll(result);totals=stats;today=loadedToday;if(a.tab.equals("Estudos")&&content!=null)draw();});});}
 void route(String name){if(name.equals("Cursos")){course=0;subject=0;}else if(name.equals("Módulos"))subject=0;section=name;query="";limit=80;libraryPage=0;saveContext();draw();reload();}
 void draw(){if(content==null||!a.tab.equals("Estudos"))return;clock.removeCallbacks(tick);timerLabel=null;content.removeAllViews();StudyUi ui=new StudyUi(a);LinearLayout header=ui.card();String kind=subject>0?"Módulo / disciplina":course>0?"Curso":"Estudos";String title=section.equals("Cursos")?AppLanguage.text(a,"Cursos"):subject>0?subjectName(subject):courseName();ui.heading(header,subject>0?"book":"course",kind,title,this::settings);LinearLayout trail=a.row();TextView home=a.button("Cursos",()->route("Cursos"));UiBox.style(home);trail.addView(home,new LinearLayout.LayoutParams(0,-2,1));if(course>0){TextView parent=a.button(courseName(),()->openCourse(course));UiBox.style(parent);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.leftMargin=a.dp(8);trail.addView(parent,lp);}if(!section.equals("Cursos")){a.gap(header,12);header.addView(trail);}LinearLayout tools=a.row();tools.addView(a.iconButton("calendar","Plano de hoje",()->route("Visão geral")),new LinearLayout.LayoutParams(a.dp(44),a.dp(44)));LinearLayout.LayoutParams createBox=new LinearLayout.LayoutParams(0,a.dp(46),1);createBox.setMargins(a.dp(8),0,a.dp(8),0);tools.addView(a.button("Criar ou importar",this::createMenu),createBox);if(!section.equals("Cursos"))tools.addView(a.iconButton("search","Pesquisar nos estudos",this::search),new LinearLayout.LayoutParams(a.dp(44),a.dp(44)));LinearLayout.LayoutParams toolsBox=new LinearLayout.LayoutParams(-1,-2);toolsBox.topMargin=a.dp(10);header.addView(tools,toolsBox);TextView assistant=a.button("Estudar com Seeky",this::seekyMenu);UiBox.style(assistant);LinearLayout.LayoutParams assistantBox=new LinearLayout.LayoutParams(-1,a.dp(48));assistantBox.topMargin=a.dp(9);header.addView(assistant,assistantBox);content.addView(header);a.gap(content,14);
 if(!section.equals("Cursos")){HorizontalScrollView strip=new HorizontalScrollView(a);strip.setHorizontalScrollBarEnabled(false);LinearLayout tabs=a.row();String[] options=subject>0?new String[]{"Biblioteca","Visão geral","Cadernos","Cartões","Perguntas","Agenda","Progresso"}:new String[]{"Módulos","Visão geral","Biblioteca","Cadernos","Cartões","Perguntas","Agenda","Progresso"};for(String name:options){TextView chip=a.button(name.equals("Visão geral")?"Hoje":name,()->route(name));UiBox.style(chip);chip.setTextSize(12);if(name.equals(section)){chip.setBackground(a.shape(a.accent,12));chip.setTextColor(AppPalette.of(a).light?Color.WHITE:0xff10141d);}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,a.dp(44));lp.rightMargin=a.dp(8);tabs.addView(chip,lp);}strip.addView(tabs);content.addView(strip);a.gap(content,14);}if(!query.isEmpty())content.addView(a.button("Pesquisa: "+query+" ×",()->{query="";reload();}));
 switch(section){case "Cursos":courses();break;case "Módulos":modules();break;case "Biblioteca":library();break;case "Cadernos":notes();break;case "Cartões":cards();break;case "Perguntas":questions();break;case "Agenda":planner();break;case "Progresso":progress();break;default:overview();}if(loading)content.addView(a.label("A actualizar os seus dados…",11,a.muted));}
 void hero(String title,String sub,String button,Runnable action){LinearLayout card=a.card();GradientDrawable background=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{AppPalette.of(a).heroStart,AppPalette.of(a).heroEnd});background.setCornerRadius(a.dp(24));card.setBackground(background);TextView heading=a.label(title,22,Color.WHITE);heading.setTypeface(null,Typeface.BOLD);card.addView(heading);card.addView(a.label(sub,12,0xddffffff));a.gap(card,10);TextView b=a.button(button,action);b.setBackground(a.shape(0x22ffffff,14));b.setTextColor(Color.WHITE);card.addView(b);content.addView(card);a.gap(content,13);}
 void pair(String first,String subtitle,Runnable one,String second,String sub2,Runnable two){LinearLayout row=a.row();for(int i=0;i<2;i++){final Runnable go=i==0?one:two;LinearLayout card=a.card();card.setPadding(a.dp(13),a.dp(14),a.dp(13),a.dp(14));card.addView(a.title(i==0?first:second,20));card.addView(a.label(i==0?subtitle:sub2,11,a.muted));card.setOnClickListener(v->go.run());Motion.touch(card);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);if(i==0)p.rightMargin=a.dp(9);row.addView(card,p);}content.addView(row);a.gap(content,10);}
