 void overview(){new StudyToday(this).draw(false);}
 long pendingTasks(){long n=0;for(StudyStore.Row r:rows("tasks"))if(r.n("done")==0)n++;return n;}
 void chooseSubject(){String[] opts=new String[subjects.size()+2];opts[0]="Módulos e disciplinas";for(int i=0;i<subjects.size();i++)opts[i+1]=subjects.get(i).s("title");opts[opts.length-1]="+ Criar módulo ou disciplina";a.dialog().setTitle("O que vai estudar?").setItems(opts,(d,i)->{if(i==opts.length-1){subjectForm(null);return;}if(i==0){subject=0;route(course>0?"Módulos":"Visão geral");}else openSubject(subjects.get(i-1));}).setNegativeButton("Fechar",null).show();}
 void createMenu(){a.dialog().setTitle("Acrescentar aos estudos").setItems(new String[]{"Criar curso","Criar módulo ou disciplina","Importar livros e materiais","Criar anotação / resumo","Criar cartão de estudo","Criar pergunta e resposta","Criar tarefa de estudo"},(d,i)->{switch(i){case 0:courseForm(null);break;case 1:subjectForm(null);break;case 2:pickMaterials();break;case 3:withSubject(()->noteForm(null,0,0,""));break;case 4:withSubject(()->cardForm(null,0,0,"",""));break;case 5:withSubject(()->questionForm(null));break;case 6:withSubject(()->taskForm(null));}}).setNegativeButton("Fechar",null).show();}

 void search(){EditText q=field("Título, conteúdo, palavra-chave ou etiqueta",query,false);a.dialog().setTitle("Pesquisar nos estudos").setMessage("Pesquisa os registos da secção e disciplina escolhidas. O texto integral de um livro é pesquisado dentro do leitor.").setView(q).setPositiveButton("Procurar",(d,w)->{query=q.getText().toString().trim();limit=80;libraryPage=0;reload();}).setNegativeButton("Cancelar",null).show();}
 EditText field(String hint,String value,boolean multi){EditText e=new EditText(a);e.setHint(hint);e.setText(value);e.setTextSize(15);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(200000)});e.setSingleLine(!multi);if(multi){e.setMinLines(3);e.setGravity(Gravity.TOP);}return e;}
 void input(LinearLayout f,String label,EditText e){f.addView(a.label(label,11,a.muted));f.addView(e,new LinearLayout.LayoutParams(-1,-2));}
 interface Save {void run()throws Exception;}
 void form(String title,LinearLayout view,Save save){AlertDialog d=a.dialog().setTitle(title).setView(view).setPositiveButton("Guardar",null).setNegativeButton("Cancelar",null).create();d.show();d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{save.run();d.dismiss();}catch(Exception e){a.toast(e.getMessage());}});}
 ChoiceSpinner subjectField(LinearLayout form,long current){ChoiceSpinner spinner=new ChoiceSpinner(a);List<String> labels=new ArrayList<>();List<Long> keys=new ArrayList<>();labels.add(AppLanguage.text(a,course>0?"Escolher módulo ou disciplina":"Geral / sem disciplina"));keys.add(0L);int selected=0;for(StudyStore.Row row:subjects){labels.add(row.s("title"));keys.add(row.id());if(row.id()==current)selected=keys.size()-1;}spinner.setTag(keys);spinner.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_item,labels));spinner.setSelection(selected);form.addView(a.label("Módulo ou disciplina",11,a.muted));form.addView(spinner);return spinner;}
 @SuppressWarnings("unchecked") long chosen(ChoiceSpinner spinner){List<Long> keys=(List<Long>)spinner.getTag();long id=keys.get(spinner.getSelectedItemPosition());if(course>0&&id==0)throw new IllegalArgumentException("Escolha um módulo ou disciplina.");return id;}
 void subjectForm(StudyStore.Row row){LinearLayout form=a.column();EditText name=field("Nome do módulo ou disciplina",row==null?"":row.s("title"),false);input(form,"Nome",name);ChoiceSpinner type=new ChoiceSpinner(a);type.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_item,new String[]{AppLanguage.text(a,"Módulo"),AppLanguage.text(a,"Disciplina")}));type.setSelection(row!=null&&row.s("kind").equals("subject")?1:0);form.addView(type);List<StudyStore.Row> parentCourses=new ArrayList<>(courses);List<String> labels=new ArrayList<>();labels.add(AppLanguage.text(a,"Sem curso"));int selected=0;long parent=row==null?course:row.n("course");for(StudyStore.Row c:parentCourses){labels.add(c.s("title"));if(c.id()==parent)selected=labels.size()-1;}ChoiceSpinner parentField=new ChoiceSpinner(a);parentField.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_item,labels));parentField.setSelection(selected);form.addView(a.label("Curso",11,a.muted));form.addView(parentField);form(row==null?"Criar módulo ou disciplina":"Editar módulo ou disciplina",form,()->{String title=StudySchedule.valid(name.getText().toString(),80,"Módulo");long chosenCourse=parentField.getSelectedItemPosition()==0?0:parentCourses.get(parentField.getSelectedItemPosition()-1).id();String kind=type.getSelectedItemPosition()==0?"module":"subject";job(()->{long id=db.save("subjects",row==null?0:row.id(),StudyStore.values("title",title,"color",a.accent,"created",row==null?System.currentTimeMillis():row.n("created"),"course",chosenCourse,"kind",kind));CloudJobs.schedule(a);StudyStore.Row saved=db.get("subjects",id);a.ui(()->{if(saved!=null)openSubject(saved);else reload();});});});}
 void saveContext(){prefs.edit().putLong("course",course).putLong("subject",subject).putString("section",section).apply();}
 void openCourse(long id){course=id;subject=0;section="Módulos";query="";limit=80;libraryPage=0;subjects=new ArrayList<>();data.clear();totals=new long[9];loading=true;saveContext();draw();reload();}
 void openSubject(StudyStore.Row row){course=row.n("course");subject=row.id();section="Biblioteca";query="";limit=80;libraryPage=0;data.clear();totals=new long[9];loading=true;saveContext();draw();reload();}
 String courseName(){for(StudyStore.Row row:courses)if(row.id()==course)return row.s("title");return "Todos os estudos";}
 void courses(){new StudyToday(this).draw(true);a.section(content,"Os seus cursos",null);StudyUi ui=new StudyUi(a);if(courses.isEmpty()&&!loading)empty("Os seus cursos","Organize os materiais por módulo ou disciplina.","Criar curso",()->courseForm(null));for(StudyStore.Row row:courses){LinearLayout card=ui.card();ui.heading(card,"course","Curso",row.s("title"),()->courseMenu(row));if(!row.s("description").isEmpty()){a.gap(card,12);card.addView(ui.raw(row.s("description"),12,a.muted));}ui.stats(card,row.n("module_count")+" "+AppLanguage.text(a,"módulos / disciplinas"),row.n("material_count")+" "+AppLanguage.text(a,"materiais"));ui.actions(card,"Abrir curso",()->openCourse(row.id()),null,null);card.setOnClickListener(v->openCourse(row.id()));Motion.touch(card);content.addView(card);a.gap(content,12);}TextView create=a.primary("+ Criar curso",()->courseForm(null));content.addView(create);a.gap(content,10);TextView all=a.button("Todos os estudos",()->{course=0;subject=0;route("Visão geral");saveContext();});UiBox.style(all);content.addView(all);}
 void modules(){StudyUi ui=new StudyUi(a);int number=0;for(StudyStore.Row row:subjects){LinearLayout card=ui.card();ui.unitHeading(card,row.s("kind").equals("module")?"Módulo":"Disciplina",row.s("title"),++number,()->subjectMenu(row));ui.stats(card,row.n("material_count")+" "+AppLanguage.text(a,"materiais"),AppLanguage.text(a,"Leitura")+" · "+row.n("progress")+"%");ui.progress(card,(int)row.n("progress"));ui.actions(card,"Abrir materiais",()->openSubject(row),"Importar",()->{openSubject(row);pickMaterials();});content.addView(card);a.gap(content,12);}if(subjects.isEmpty()&&!loading)empty("Módulos e disciplinas","Crie um módulo para adicionar materiais e atividades.","Criar módulo",()->subjectForm(null));content.addView(a.primary("+ Criar módulo ou disciplina",()->subjectForm(null)));}
 void courseForm(StudyStore.Row row){LinearLayout form=a.column();EditText title=field("Nome do curso",row==null?"":row.s("title"),false),description=field("Descrição",row==null?"":row.s("description"),true);description.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2000)});input(form,"Curso",title);input(form,"Descrição",description);form(row==null?"Criar curso":"Editar curso",form,()->{String name=StudySchedule.valid(title.getText().toString(),120,"Curso"),detail=description.getText().toString().trim();job(()->{long id=db.save("courses",row==null?0:row.id(),StudyStore.values("title",name,"description",detail,"created",row==null?System.currentTimeMillis():row.n("created")));CloudJobs.schedule(a);a.ui(()->openCourse(id));});});}
 void courseMenu(StudyStore.Row row){new UiDialog.Builder(a).setTitle(row.s("title")).setItems(new String[]{"Abrir curso","Editar curso","Remover curso"},(d,n)->{if(n==0)openCourse(row.id());else if(n==1)courseForm(row);else a.dialog().setTitle("Remover curso?").setMessage("Os módulos, materiais e atividades serão conservados em Todos os estudos.").setPositiveButton("Remover",(x,w)->mutate(()->{db.deleteCourse(row.id());a.ui(()->{course=0;subject=0;section="Cursos";saveContext();});})).setNegativeButton("Cancelar",null).show();}).show();}
 void subjectMenu(StudyStore.Row row){new UiDialog.Builder(a).setTitle(row.s("title")).setItems(new String[]{"Abrir","Editar módulo ou disciplina","Caderno de revisão em PDF","Remover módulo"},(d,n)->{if(n==0)openSubject(row);else if(n==1)subjectForm(row);else if(n==2)ToolsActivity.revision(a,row.id(),row.s("title"));else a.dialog().setTitle("Remover módulo?").setMessage("Os materiais e atividades serão conservados em Todos os estudos.").setPositiveButton("Remover",(x,w)->mutate(()->{db.deleteSubject(row.id());a.ui(()->{if(subject==row.id()){subject=0;section="Módulos";saveContext();}});})).setNegativeButton("Cancelar",null).show();}).show();}
 void withSubject(Runnable next){if(loading){a.toast(AppLanguage.text(a,"A actualizar os seus dados…"));return;}if(course==0||subject>0){next.run();return;}List<StudyStore.Row> choices=new ArrayList<>(subjects);String[] names=new String[choices.size()+1];for(int i=0;i<choices.size();i++)names[i]=choices.get(i).s("title");names[names.length-1]="+ Criar módulo ou disciplina";a.dialog().setTitle("Escolher módulo ou disciplina").setItems(names,(d,n)->{if(n==choices.size())subjectForm(null);else{subject=choices.get(n).id();saveContext();next.run();}}).show();}
 void library(){new StudyShelf(this).show();}
 void pickMaterials(){if(course>0&&subject==0){withSubject(this::pickMaterials);return;}prefs.edit().putLong("import_subject",subject).apply();try{a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true),40);}catch(Exception e){a.showError(e);}}
 void imported(Intent data){imported(data,false);}
 void imported(Intent data,boolean forBooks){ImportWork.selected(a,data,forBooks?0:prefs.getLong("import_subject",0),forBooks);}

 void showImportReport(){String summary=prefs.getString("import_summary","");if(summary.isEmpty()){a.toast("Ainda não há relatório de importação.");return;}a.dialog().setTitle("Resultado da importação").setMessage(summary+"\n\nOs originais foram conservados.").setPositiveButton("Concluir",null).setNeutralButton("Guardar relatório CSV",(d,w)->{try{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/csv").putExtra(Intent.EXTRA_TITLE,"Seeky_Importacao.csv");a.startActivityForResult(i,IMPORT_REPORT);}catch(Exception e){a.showError(e);}}).show();}
 void exportImportReport(Uri target){final String name=prefs.getString("import_report","");job(()->{try{File report=new File(StudyImporter.reports(a),name).getCanonicalFile();if(name.isEmpty()||!report.getParentFile().equals(StudyImporter.reports(a).getCanonicalFile())||!report.isFile())throw new IOException("Relatório indisponível.");try(InputStream in=new FileInputStream(report);OutputStream out=a.getContentResolver().openOutputStream(target,"wt")){if(out==null)throw new IOException("Destino indisponível.");byte[] buffer=new byte[65536];for(int n;(n=in.read(buffer))!=-1;)out.write(buffer,0,n);}a.ui(()->a.toast("Relatório de importação guardado."));}catch(Exception e){a.ui(()->a.showError(e));}});}
