 void importCards(){EditText input=field("Pergunta[TAB]Resposta[TAB]Etiqueta\nUma linha por cartão","",true);input.setMinLines(7);a.dialog().setTitle("Importar cartões TSV").setMessage("Cole até 500 linhas. Cada linha precisa de pergunta e resposta separadas por uma tabulação.").setView(input).setPositiveButton("Importar",(d,w)->{String value=input.getText().toString();long group=subject;job(()->{String[] lines=value.split("\\r?\\n");if(lines.length>500)throw new IllegalArgumentException("Limite de 500 cartões por importação.");List<String[]> checked=new ArrayList<>();for(String line:lines){if(line.trim().isEmpty())continue;String[] cells=line.split("\\t",-1);if(cells.length<2)throw new IllegalArgumentException("Falta tabulação numa das linhas.");StudySchedule.valid(cells[0],5000,"Pergunta");StudySchedule.valid(cells[1],20000,"Resposta");checked.add(cells);}android.database.sqlite.SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{for(String[] cells:checked)db.save("cards",0,StudyStore.values("subject",group,"front",cells[0].trim(),"back",cells[1].trim(),"tags",cells.length>2?cells[2]:"","due",System.currentTimeMillis(),"updated",System.currentTimeMillis()));sql.setTransactionSuccessful();}finally{sql.endTransaction();}a.ui(()->{a.toast(checked.size()+" cartões importados.");reload();});});}).setNegativeButton("Cancelar",null).show();}
