 void result(int request,int result,Intent intent){if(result!=Activity.RESULT_OK||intent==null)return;if(request==40){imported(intent);return;}if(request==IMPORT_REPORT){if(intent.getData()!=null)exportImportReport(intent.getData());return;}Uri uri=intent.getData();if(uri==null)return;if(request==41){a.toast("A preparar cópia de segurança… mantenha o Seeky aberto.");job(()->{try(OutputStream out=a.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Destino indisponível.");StudyBackup.write(a,db,out);prefs.edit().putLong("last_manual_export",System.currentTimeMillis()).apply();a.ui(()->{a.toast("Cópia de Estudos guardada.");draw();});}catch(Exception e){throw new IllegalStateException("Não foi possível concluir a cópia. Apague o ZIP incompleto e repita: "+e.getMessage(),e);}});}else if(request==42){a.toast("A verificar e importar a cópia… mantenha o Seeky aberto.");job(()->{File temp=new File(a.getCacheDir(),"study-restore-"+UUID.randomUUID()+".zip");try{try(InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Cópia indisponível.");StudyFiles.copy(in,temp,StudyBackup.MAX,()->a.dead);}int n=StudyBackup.restore(a,db,temp);CloudJobs.schedule(a);a.ui(()->{a.toast(n+" registos importados com os materiais.");reload();});}catch(Exception e){throw new IllegalStateException("Importação: "+e.getMessage(),e);}finally{temp.delete();}});}else if(request==43){String note=prefs.getString("export_note","");job(()->{try(OutputStream out=a.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Destino indisponível.");out.write(note.getBytes("UTF-8"));a.ui(()->a.toast("Anotação exportada."));}catch(Exception e){throw new IllegalStateException(e);}});}}
